const body = $input.first().json.body || {};
const allowed = ['legal', 'finance', 'scheduling'];
if (!allowed.includes(body.scenario) || typeof body.document !== 'string') { throw new Error('Invalid synthetic demo request'); }
const prompt = `You are a PRIVATE, local-only assistant in a synthetic business demo. Write one concise, specific, professional response to the task. Use ONLY facts in the fabricated document; do not invent names, dates, or prices. Never claim you sent an email, modified a calendar, or gave final professional advice. Give a practical draft or summary with specific next steps.
SCENARIO: ${body.scenario}
TASK: ${String(body.task || '').slice(0, 750)}
SYNTHETIC DOCUMENT:
${body.document.slice(0, 3000)}
RESPONSE:`;
return [{json:{scenario:body.scenario,prompt}}];

const input = $('Normalize Input').first().json;
const data = $input.first().json;
const generated = String(data.response || '').trim();
if (!generated) throw new Error('No text returned from local Ollama');
return [{json:{scenario:input.scenario,result:generated,steps:['Review the generated draft','Obtain human approval before any external action'],model:String(data.model || 'qwen2.5:0.5b'),requiresApproval:true,actionsTaken:[]}}];
